      "statements": [
        {
          "key": "공학적 관리 및 개인보호구",
          "value": "참조하여 작업하시오."
        ,
          "line": "p4:L24"
        },
        {
          "value": "모든 안전 주의를 읽고 이해하기 전에는 취급하지 마시오."
        ,
          "line": "p4:L25"
        },
        {
          "value": "사용 전에 사용설명서를 입수하시오."
        ,
          "line": "p4:L26"
        },
        {
          "value": "용기가 비워진 후에도 제품 찌꺼기(증기, 액체, 고체)가 남아 있을 수 있으므로 모든 MSDS, 라벨 예방조치를 따르시오."
        ,
          "line": "p4:L27"
        },
        {
          "value": "장기간 또는 반복적으로 증기를 흡입하지 마시오."
        ,
          "line": "p4:L28"
        }
      ]
    ,
      "suggested_code": "S7_HANDLING"
    ,
      "line": "p4:L23"
    },
    {
      "after_item": "S7_STORAGE",
      "title_raw": "나. 안전한 저장 방법",
      "reason": "코드없음",
      "statements": [
        {
          "value": "누출여부를 주기적으로 점검하시오."
        ,
          "line": "p4:L30"
        },
        {
          "value": "사용하지 않을 시에는 밀폐하여 놓으시오."
        ,
          "line": "p4:L31"
        },
        {
          "value": "서늘하고 건조하며 통풍이 잘 되는 장소에 저장하시오."
        ,
          "line": "p4:L32"
        },
        {
          "value": "손상된 용기는 사용하지 마시오."
        ,
          "line": "p4:L33"
        },
        {
          "value": "용기에 물리적인 충격을 가하지 마시오."
        ,
          "line": "p4:L34"
        }
      ]
    ,
      "suggested_code": "S7_STORAGE"
    ,
      "line": "p4:L29"
    }
  ]
}

